<?php
declare(strict_types=1);
function lc_schedule_parse(string $json,int $total,int $project):array{
 try{$rows=json_decode($json,true,32,JSON_THROW_ON_ERROR);}catch(Throwable $e){crm_fail(422,'График оплаты: нужен список этапов JSON.');}
 if(!is_array($rows)||!array_is_list($rows)||!count($rows)||count($rows)>24)crm_fail(422,'График оплаты: от 1 до 24 этапов.');$out=[];$sum=0;
 foreach($rows as $row){if(!is_array($row)||array_diff(array_keys($row),['label','amount','due_on','gate','stage_id']))crm_fail(422,'Проверьте поля этапа оплаты.');$label=cc_text($row,'label',190);$amount=bill_minor($row['amount']??null);if($amount<1)crm_fail(422,'Сумма этапа должна быть положительной.');$date=pricing_date($row,'due_on');$gate=$row['gate']??'';if(!in_array($gate,['production','milestone','acceptance','handover','closure','none'],true))crm_fail(422,'Выберите условие этапа оплаты.');$stage=$row['stage_id']??null;if($gate==='milestone'){cc_id($stage);if(!crm_query('SELECT id FROM nd_project_stages WHERE id=? AND project_id=?',[$stage,$project])->fetchColumn())crm_fail(422,'Выберите этап этого проекта.');}elseif($stage!==null)crm_fail(422,'ID этапа нужен только для поэтапного платежа.');$sum+=$amount;$out[]=['label'=>$label,'amount_minor'=>$amount,'due_on'=>$date,'gate'=>$gate,'stage_id'=>$stage];}
 if($sum!==$total)crm_fail(422,'Сумма этапов оплаты должна точно совпадать с одобренной ценой.');return $out;
}
function lc_paid_at(array $d):string{$s=cc_text($d,'paid_at',19);$date=DateTimeImmutable::createFromFormat('!Y-m-d H:i:s',$s,new DateTimeZone('Europe/Kaliningrad'));if(!$date||$date->format('Y-m-d H:i:s')!==$s||$date->getTimestamp()>time()+300)crm_fail(422,'Укажите реальное время платежа по Калининграду.');return $date->setTimezone(new DateTimeZone('UTC'))->format('Y-m-d H:i:s');}
function lc_receipt_due(string $utc,string $method):string{$paid=new DateTimeImmutable($utc,new DateTimeZone('UTC'));if(in_array($method,['cash','electronic'],true))return $utc;if($method!=='bank_other')crm_fail(422,'Выберите способ расчёта по фактическим банковским данным.');return $paid->setTimezone(new DateTimeZone('Europe/Kaliningrad'))->modify('first day of next month')->setTime(23,59,59)->modify('+8 days')->setTimezone(new DateTimeZone('UTC'))->format('Y-m-d H:i:s');}
